<script>
 import {onMount,tick,untrack} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {colorSyncWindow,colorSyncCapabilities} from './colorsync-state.js';
 import {COLOR_FILTERS,COLOR_SPACES} from './colorsync-engine.js';
 import {colorSyncMenus} from './colorsync-menus.js';
 import {createColorSyncNativeView} from './colorsync-native-view.js';
 import './colorsync.css';
 let {state: colorSyncState,profile,window:actualWindow=null,windowId:providedId=null,execute,registerView,available=true,active=true,controls={}}=$props();
 const windowId=$derived(providedId??actualWindow?.id),session=$derived(colorSyncWindow(colorSyncState,windowId)),cap=$derived(colorSyncCapabilities(profile)),menus=$derived(colorSyncMenus({state: colorSyncState,profile,windowId})),menu=$derived(menus.find(m=>m.id===session?.menu));
 const selected=$derived(colorSyncState.profiles.find(p=>p.id===session?.selectedId)),device=$derived(colorSyncState.devices.find(d=>d.id===session?.deviceId));
 const tabs=[['firstaid','Profile First Aid','✚'],['profiles','Profiles','◈'],['devices','Devices','▣'],['filters','Filters','◩'],['calculator','Calculator','▦']];
 let root=$state(null),canvas=$state(null),facade=$state(null),message=$state(''),info=$state(null),comparison=$state(null),image=$state(null),mounted=$state(false),tagId=$state(null),plotMode=$state('lab'),rotation=$state(30),drag=$state(null);
 let originalState,originalProfile,originalId,originalSession,originalWindow,retired=false,requestGeneration=0,imageGeneration=0;
 const current=()=>!retired&&!!session&&root?.isConnected===true&&colorSyncState===originalState&&profile===originalProfile&&windowId===originalId&&actualWindow===originalWindow&&session===originalSession&&(!actualWindow||actualWindow.id===windowId&&actualWindow.appId==='colorsync');
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const response=await execute(`colorsync.${suffix}`,{windowId},payload);if(current())message=response?.status==='applied'?'':response?.error?.message??'Actual ColorSync operation unavailable.';return response;}
 async function menuAction(item){if(!item.enabled||!item.request||!current())return;const response=await execute(item.request.command,item.request.target,item.request.payload);if(current()){message=response?.status==='applied'?'':response?.error?.message??'Native menu unavailable.';if(response?.status==='applied')command('menu',{menu:null});}}
 async function loadInfo(id,heldId,signature){const generation=++requestGeneration;info=null;comparison=null;tagId=null;if(!current()||!available)return;const result=await execute('colorsync.profile.info',{windowId},{profileId:id});if(!current()||generation!==requestGeneration||JSON.stringify(selected)!==signature)return;if(result?.status==='applied'){info=result;tagId=result.metadata.tags[0]?.signature??null;}else message=result?.error?.message??'ICC source unavailable.';if(heldId){const held=await execute('colorsync.profile.info',{windowId},{profileId:heldId});if(current()&&generation===requestGeneration&&session.compareId===heldId&&held?.status==='applied')comparison=held;}}
 async function loadImage(id,revision){const generation=++imageGeneration;image=null;if(!id||!current()||!available)return;const result=await execute('colorsync.image.info',{windowId},{});if(current()&&generation===imageGeneration&&session.imageFileId===id&&session.imageRevision===revision){if(result?.status==='applied')image=result;else message=result?.error?.message??'Original image unavailable.';}}
 function draw(){if(!canvas)return;const context=canvas.getContext('2d');if(!context)return;context.fillStyle='#f5f5f5';context.fillRect(0,0,500,400);context.strokeStyle='#d8d8d8';context.lineWidth=.5;for(let n=1;n<10;n++){context.beginPath();context.moveTo(n*50,0);context.lineTo(n*50,400);context.moveTo(0,n*40);context.lineTo(500,n*40);context.stroke();}
 const angle=rotation*Math.PI/180,project=([l,a,b])=>[250+(a*Math.cos(angle)-b*Math.sin(angle))*1.3,340-l*2.7+(a*Math.sin(angle)+b*Math.cos(angle))*.4];
 for(const [data,color] of [[comparison,'#b7bed580'],[info,'#4475aa']]){if(!data)continue;context.strokeStyle=color;context.lineWidth=comparison&&data===comparison?1.1:.8;if(plotMode==='lab'&&data.labPaths){for(const path of data.labPaths){context.beginPath();path.forEach((p,index)=>{const [x,y]=project(p);if(index)context.lineTo(x,y);else context.moveTo(x,y);});context.stroke();}}else if(plotMode==='xy'&&data.gamut){context.beginPath();data.gamut.forEach(([x,y],index)=>{if(index)context.lineTo(x*600+30,370-y*450);else context.moveTo(x*600+30,370-y*450);});context.closePath();context.stroke();}}
 context.fillStyle='#555';context.font='11px sans-serif';context.fillText(plotMode==='lab'?'L* a* b* · actual RGB matrix/curve gamut, D50':'CIE xy · actual ICC matrix primaries',12,18);if(info&&!info.labPaths&&plotMode==='lab')context.fillText('This profile has no supported matrix/curve gamut.',12,205);}
 function component(index,value){command('calculator',{components:session.components.map((n,i)=>i===index?Number(value):n)});}
 async function drop(event){event.preventDefault();let id=event.dataTransfer?.getData('application/x-jesteros-file-id');if(!id){try{id=JSON.parse(event.dataTransfer?.getData('application/x-jesteros-file-ids')||'[]')[0];}catch{}}if(typeof id==='string')await command(session.tab==='image'?'image.open':'profile.import',{fileId:id});}
 function keyboard(event){if(!current()||!available||!active)return;const modifier=cap.windows?event.ctrlKey:event.metaKey;if(modifier&&event.key.toLowerCase()==='o'){event.preventDefault();command(session.tab==='image'?'image.open':'profile.import');}else if(event.key==='Escape')command('menu',{menu:null});}
 $effect(()=>{const id=selected?.id,held=session?.compareId,signature=JSON.stringify(selected),ready=mounted&&available&&active;if(ready&&id)untrack(()=>loadInfo(id,held,signature));});
 $effect(()=>{const id=session?.imageFileId,revision=session?.imageRevision,ready=mounted&&available&&active;if(ready)untrack(()=>loadImage(id,revision));});
 $effect(()=>{info;comparison;rotation;plotMode;canvas;draw();});
 onMount(()=>{originalState=colorSyncState;originalProfile=profile;originalId=windowId;originalSession=session;originalWindow=actualWindow;facade=createColorSyncNativeView({getRoot:()=>root,getState:()=>colorSyncState,getProfile:()=>profile,windowId,available:()=>current()&&available&&active,tick});registerView?.(windowId,facade);mounted=true;return()=>{retired=true;requestGeneration++;imageGeneration++;facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="colorsync-app" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} role="region" aria-label={cap.label} data-colorsync-window-id={windowId} data-profile={typeof profile==='string'?profile:profile.id} tabindex="0" onkeydown={keyboard} ondragover={event=>event.preventDefault()} ondrop={drop}>
 {#if session}
 <header class="colorsync-titlebar">{#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen} zoomed={controls.zoomed}/>{/if}<strong>{cap.label}</strong></header>
 <nav class="colorsync-menu-strip" aria-label="Application menus">{#each menus.filter(m=>m.id!=='colorsync') as group}<button data-colorsync-control={`menu:${group.id}`} aria-expanded={session.menu===group.id} onclick={()=>command('menu',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav>
 {#if menu}<div class="colorsync-menu" role="menu">{#each menu.children as item}<button role="menuitem" disabled={!item.enabled} data-colorsync-control={`menuitem:${item.id}`} onclick={()=>menuAction(item)}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 <nav class="colorsync-toolbar" aria-label="ColorSync tools" inert={!available||!active}>{#each tabs as [id,label,icon]}<button class:selected={session.tab===id} data-colorsync-control={`tab:${id}`} aria-pressed={session.tab===id} onclick={()=>command('tab',{tab:id})}><span class={`colorsync-tool-icon ${id}`}>{icon}</span>{label}</button>{/each}<button data-colorsync-control="tab:image" class="colorsync-image-tool" class:selected={session.tab==='image'} onclick={()=>command('tab',{tab:'image'})}><span>▧</span>Image</button></nav>
 {#if cap.windows||cap.golden}<p class="colorsync-disclosure">{cap.disclosure}</p>{/if}
 <div class="colorsync-workspace" inert={!available||!active}>
 {#if session.tab==='firstaid'}
 <section class="colorsync-firstaid"><h2>Profile First Aid</h2><p>Verify the actual local ICC profiles. Supported repairs preserve the source and create a repaired ICC file.</p><div class="colorsync-report" role="log" aria-label="Profile verification results">{#if !session.reports.length}<p>Click Verify to inspect profile signature, header and tag metadata.</p>{/if}{#each session.reports as report}<article><button data-colorsync-control={`report:${report.id}`} onclick={()=>command('profile.select',{profileId:report.id})}>{report.valid?'✓':'⚠'} {colorSyncState.profiles.find(p=>p.id===report.id)?.name}</button>{#if report.valid}<p>Passed supported structural verification.</p>{:else}{#each report.issues as issue}<p>{issue}</p>{/each}{/if}</article>{/each}</div><div class="colorsync-actions"><label>Repair profile <select data-colorsync-control="repair-profile" value={session.selectedId} onchange={event=>command('profile.select',{profileId:event.currentTarget.value})}>{#each colorSyncState.profiles as p}<option value={p.id}>{p.name}</option>{/each}</select></label><button data-colorsync-control="verify" onclick={()=>command('profile.verify',{all:true})}>Verify</button><button data-colorsync-control="repair" disabled={!session.reports.find(r=>r.id===session.selectedId&&r.repairable.length&&r.repairable.length===r.issues.length)} onclick={()=>command('profile.repair')}>Repair to new ICC…</button></div><p class="colorsync-note">Missing tags, LUT transforms, v4 profile-ID checksums and calibration are not repaired or certified.</p></section>
 {:else if session.tab==='profiles'}
 <aside class="colorsync-sidebar"><h3>▾ Local profiles</h3>{#each colorSyncState.profiles as p}<button class:selected={p.id===session.selectedId} data-colorsync-control={`profile:${p.id}`} onclick={()=>command('profile.select',{profileId:p.id})}>◈ {p.name}</button>{/each}<button class="colorsync-open" data-colorsync-control="import" onclick={()=>command('profile.import')}>Open ICC…</button></aside>
 <main class="colorsync-profile-detail"><header><strong>{selected?.name}</strong><button data-colorsync-control="export-profile" onclick={()=>command('profile.export')}>Export ICC…</button></header><div class="colorsync-plot-controls"><select data-colorsync-control="plot-mode" aria-label="Gamut plot view" bind:value={plotMode}><option value="lab">Lab plot · matrix/curve subset</option><option value="xy">CIE xy primaries</option></select><button data-colorsync-control="hold" disabled={!info?.gamut} onclick={()=>command('profile.compare')}>Hold for Comparison</button>{#if session.compareId}<button data-colorsync-control="clear-compare" onclick={()=>command('profile.compare',{profileId:null})}>Clear Comparison</button>{/if}</div>
 <canvas bind:this={canvas} width="500" height="400" aria-label="Actual ICC matrix gamut canvas; drag to rotate Lab plot" data-colorsync-control="gamut" tabindex="0" onpointerdown={event=>{drag={x:event.clientX,rotation};canvas.setPointerCapture(event.pointerId);}} onpointermove={event=>{if(drag)rotation=drag.rotation+(event.clientX-drag.x)*.5;}} onpointerup={()=>drag=null} onpointercancel={()=>drag=null}>Actual ICC gamut canvas.</canvas>
 {#if info}<dl><dt>Signature</dt><dd>{info.metadata.signature}</dd><dt>Version / size</dt><dd>{info.metadata.version} / {info.metadata.size} bytes</dd><dt>Class / space / PCS</dt><dd>{info.metadata.deviceClass} / {info.metadata.colorSpace} / {info.metadata.pcs}</dd><dt>Rendering intent</dt><dd>{info.metadata.intent}</dd></dl><div class="colorsync-tag-inspector"><select data-colorsync-control="tag" aria-label="ICC tag" bind:value={tagId}>{#each info.metadata.tags as tag}<option value={tag.signature}>{tag.signature} — {tag.type}</option>{/each}</select>{#each info.metadata.tags.filter(t=>t.signature===tagId) as tag}<p>Offset {tag.offset}, length {tag.size} bytes{tag.values.length?` · ${tag.values.map(n=>n.toFixed(6)).join(', ')}`:''}</p>{/each}</div>{/if}</main>
 {:else if session.tab==='devices'}
 <aside class="colorsync-sidebar"><h3>▾ Authored devices</h3>{#each colorSyncState.devices as row}<button class:selected={row.id===session.deviceId} data-colorsync-control={`device:${row.id}`} onclick={()=>command('device',{deviceId:row.id,profileId:row.profileId})}>▣ {row.name}</button>{/each}</aside><main class="colorsync-device-detail"><h2>{device?.name}</h2><p>Virtual {device?.kind}. No host hardware access or calibration.</p><label>Current profile<select data-colorsync-control="device-profile" value={device?.profileId} onchange={event=>command('device',{deviceId:device.id,profileId:event.currentTarget.value})}>{#each colorSyncState.profiles as p}<option value={p.id}>{p.name}</option>{/each}</select></label><p>Assignments are retained in this authored scene and shared by all ColorSync windows.</p></main>
 {:else if session.tab==='filters'}
 <aside class="colorsync-sidebar"><h3>▾ Defined RGB filters</h3>{#each Object.keys(COLOR_FILTERS) as filter}<button class:selected={session.filter===filter} data-colorsync-control={`filter:${filter}`} onclick={()=>command('filter',{filter})}>◩ {filter}</button>{/each}</aside><main class="colorsync-filter-detail"><h2>{session.filter}</h2><dl>{#each Object.entries(COLOR_FILTERS[session.filter]) as [key,value]}<dt>{key}</dt><dd>{value}</dd>{/each}</dl><p>Actual encoded RGB pixel adjustments. These are explicitly local equivalents, not native Quartz PDF filters or arbitrary ICC profile matching. PNG output preserves alpha.</p><button data-colorsync-control="filter-open-image" onclick={()=>command('image.open')}>Open image to apply…</button></main>
 {:else if session.tab==='calculator'}
 <main class="colorsync-calculator"><h2>Color Calculator</h2><p>Defined D65 conversions, normalized sRGB / XYZ components; Lab L* a* b*. No clipping or arbitrary ICC CMM.</p><div class="colorsync-conversion"><fieldset><legend>Source color</legend><select data-colorsync-control="from" aria-label="Source space" value={session.from} onchange={event=>command('calculator',{from:event.currentTarget.value})}>{#each COLOR_SPACES as space}<option value={space}>{space}</option>{/each}</select>{#each session.components as value,index}<label>Component {index+1}<input data-colorsync-control={`component:${index}`} type="number" step="any" min="-10000" max="10000" {value} onchange={event=>component(index,event.currentTarget.value)}/></label>{/each}</fieldset><button data-colorsync-control="convert" onclick={()=>command('calculator')}>Convert →</button><fieldset><legend>Destination color</legend><select data-colorsync-control="to" aria-label="Destination space" value={session.to} onchange={event=>command('calculator',{to:event.currentTarget.value})}>{#each COLOR_SPACES as space}<option value={space}>{space}</option>{/each}</select>{#each session.result??[] as value,index}<label>Component {index+1}<output>{value.toFixed(8)}</output></label>{/each}</fieldset></div><details><summary>Local capabilities</summary><p>{cap.scope}</p></details></main>
 {:else if session.tab==='image'}
 <main class="colorsync-image"><div class="colorsync-image-actions"><button data-colorsync-control="image-open" onclick={()=>command('image.open')}>Open Image…</button><select data-colorsync-control="image-filter" aria-label="Pixel filter" value={session.filter} onchange={event=>command('filter',{filter:event.currentTarget.value})}>{#each Object.keys(COLOR_FILTERS) as filter}<option value={filter}>{filter}</option>{/each}</select><button data-colorsync-control="image-apply" disabled={!session.imageFileId} onclick={()=>command('image.process')}>Apply & Save PNG…</button></div><div class="colorsync-image-preview">{#if image}<img src={image.content} alt={`Original decoded snapshot of ${image.name}`}/>{:else}<p>Open an actual image from shared Files.</p>{/if}</div><p>{image?`${image.name} · ${image.width} × ${image.height} · original revision ${image.fileRevision}`:'No original raster selected.'}</p><p class="colorsync-note">Original snapshot. Apply revalidates exact Files source, decodes and filters real pixels, then saves a separate genuine PNG. No fake profile assignment or host output.</p></main>
 {/if}
 </div><footer class="colorsync-status" aria-live="polite">{message||session.status||cap.disclosure}</footer>
 {:else}<p role="alert">Original canonical ColorSync session unavailable.</p>{/if}
</section>
